{"new_text": "    def admit_all(
        self,
        requests: list[BatchRequest],
        start_ts: float,
        tick: float = 0.25,
        deadline_s: float = 30.0,
    ) -> list[str]:
        """Enqueues requests, drains batches, and admits each via limiter within deadline."""
        for req in requests:
            self.scheduler.enqueue(req)

        batches = self.scheduler.drain_all_batches(flush_partial=True)
        admitted: list[str] = []
        now = float(start_ts)
        deadline = start_ts + deadline_s

        for batch in batches:
            for req in batch:
                admitted_req = False
                # Try multiple times with small increments until we succeed or exceed deadline
                while now <= deadline and not admitted_req:
                    ok, _ = self.limiter.try_acquire(req.prompt_tokens, now)
                    if ok:
                        admitted.append(req.request_id)
